"""Rebinding a mixed builder result to an op on itself (#34).

np.zeros((n, 3)) is tuple[int, Literal[3]], and a name first bound to
it keeps that type. Every rebinding below runs to a shape that fits it
(same rank, same literal sizes), and each was accepted before builders
kept literals, when the name was tuple[int, int]: it must stay accepted.
Ops the plugin solves keep the literal (reshape(-1, 3), dot with a
(3, 3) matrix); the rest answer unknown (Any) where the literal was.
"""
from typing import Literal, reveal_type

import numpy as np

F = np.dtype[np.float64]
R3 = np.ndarray[tuple[Literal[3], Literal[3]], F]
Shape = tuple[int, ...]


def blocker(n: int, R: R3, k: int) -> list[Shape]:
    # The stated type of each rebinding is the first binding's, so the
    # answers themselves are revealed first.
    a = np.zeros((n, 3))
    reveal_type(a.reshape(-1, 3))
    a = a.reshape(-1, 3)
    d = np.zeros((n, 3))
    reveal_type(d.reshape(n, 3))
    d = d.reshape(n, 3)
    c = np.zeros((n, 3))
    reveal_type(c.reshape((n, 3)))
    c = c.reshape((n, 3))
    q = np.zeros((n, 3))
    reveal_type(np.dot(q, R))
    q = np.dot(q, R)
    m = np.zeros((n, 3))
    reveal_type(np.matmul(m, R))
    m = np.matmul(m, R)
    # -1 next to a dynamic size, and an op left to the stubs: unknown
    # where the literal was.
    u = np.zeros((n, 3))
    reveal_type(u.reshape(n, -1))
    u = u.reshape(n, -1)
    r = np.zeros((n, 3))
    reveal_type(np.resize(r, r.shape))
    r = np.resize(r, r.shape)
    # Another operand's dynamic size where the literal was: nothing
    # proves k is not 3 (it is, below).
    w = np.zeros((3, k))
    o = np.zeros((n, 3))
    reveal_type(np.dot(o, w))
    o = np.dot(o, w)
    return [a.shape, d.shape, c.shape, q.shape, m.shape, u.shape, r.shape, o.shape]


def n3(n: int, P: np.ndarray[tuple[Literal[3], Literal[3]], F]) -> list[Shape]:
    out: list[Shape] = []
    y = np.zeros((n, 3))
    R = np.zeros((3, 3))
    L = np.zeros((n, n))
    x = np.zeros((n, 3))
    x = x.reshape(-1, 3)
    out.append(x.shape)
    x = np.zeros((n, 3))
    x = x.reshape(n, 3)
    out.append(x.shape)
    x = np.zeros((n, 3))
    x = x.reshape((n, 3))
    out.append(x.shape)
    x = np.zeros((n, 3))
    x = np.reshape(x, (n, 3))
    out.append(x.shape)
    x = np.zeros((n, 3))
    x = x.reshape(n, -1)
    out.append(x.shape)
    x = np.zeros((n, 3))
    x = x.reshape(x.shape)
    out.append(x.shape)
    x = np.zeros((n, 3))
    x = x.ravel().reshape(n, 3)
    out.append(x.shape)
    x = np.zeros((n, 3))
    x = x.flatten().reshape(-1, 3)
    out.append(x.shape)
    x = np.zeros((n, 3))
    x = x.T.T
    out.append(x.shape)
    x = np.zeros((n, 3))
    x = np.transpose(np.transpose(x))
    out.append(x.shape)
    x = np.zeros((n, 3))
    x = x.swapaxes(0, 1).swapaxes(0, 1)
    out.append(x.shape)
    x = np.zeros((n, 3))
    x = np.squeeze(np.expand_dims(x, 0), 0)
    out.append(x.shape)
    x = np.zeros((n, 3))
    x = x[None][0]
    out.append(x.shape)
    x = np.zeros((n, 3))
    x = np.dot(x, R)
    out.append(x.shape)
    x = np.zeros((n, 3))
    x = x @ R
    out.append(x.shape)
    x = np.zeros((n, 3))
    x = np.matmul(x, R)
    out.append(x.shape)
    x = np.zeros((n, 3))
    x = np.dot(L, x)
    out.append(x.shape)
    x = np.zeros((n, 3))
    x = L @ x
    out.append(x.shape)
    x = np.zeros((n, 3))
    x = np.tensordot(x, R, axes=1)
    out.append(x.shape)
    x = np.zeros((n, 3))
    x = np.einsum('...j,jk->...k', x, R)
    out.append(x.shape)
    x = np.zeros((n, 3))
    x = np.clip(x, 0, 1)
    out.append(x.shape)
    x = np.zeros((n, 3))
    x = x.clip(0, 1)
    out.append(x.shape)
    x = np.zeros((n, 3))
    x = np.clip(x, y, 1)
    out.append(x.shape)
    x = np.zeros((n, 3))
    x = np.abs(x)
    out.append(x.shape)
    x = np.zeros((n, 3))
    x = np.exp(x)
    out.append(x.shape)
    x = np.zeros((n, 3))
    x = x * y
    out.append(x.shape)
    x = np.zeros((n, 3))
    x = np.maximum(x, y)
    out.append(x.shape)
    x = np.zeros((n, 3))
    x = np.where(x > 0, x, y)
    out.append(x.shape)
    x = np.zeros((n, 3))
    x = x.sum(axis=0, keepdims=True)
    out.append(x.shape)
    x = np.zeros((n, 3))
    x = x - x.mean(axis=0, keepdims=True)
    out.append(x.shape)
    x = np.zeros((n, 3))
    x = x / x.sum(axis=-1, keepdims=True)
    out.append(x.shape)
    x = np.zeros((n, 3))
    x = np.cumsum(x, axis=0)
    out.append(x.shape)
    x = np.zeros((n, 3))
    x = np.sort(x, axis=0)
    out.append(x.shape)
    x = np.zeros((n, 3))
    x = np.concatenate([x, y], axis=0)
    out.append(x.shape)
    x = np.zeros((n, 3))
    x = np.vstack([x, y])
    out.append(x.shape)
    x = np.zeros((n, 3))
    x = np.stack([x, y])[0]
    out.append(x.shape)
    x = np.zeros((n, 3))
    x = x.astype(np.float64)
    out.append(x.shape)
    x = np.zeros((n, 3))
    x = x[...]
    out.append(x.shape)
    x = np.zeros((n, 3))
    x = x[:2]
    out.append(x.shape)
    x = np.zeros((n, 3))
    x = x[:, ::-1]
    out.append(x.shape)
    x = np.zeros((n, 3))
    x = x[x[:, 0] > 0]
    out.append(x.shape)
    x = np.zeros((n, 3))
    x = x[[0, 1]]
    out.append(x.shape)
    x = np.zeros((n, 3))
    x = x / np.linalg.norm(x, axis=-1, keepdims=True)
    out.append(x.shape)
    x = np.zeros((n, 3))
    x = np.linalg.norm(x, axis=0, keepdims=True)
    out.append(x.shape)
    x = np.zeros((n, 3))
    x = np.roll(x, 1, axis=0)
    out.append(x.shape)
    x = np.zeros((n, 3))
    x = np.flip(x, 0)
    out.append(x.shape)
    x = np.zeros((n, 3))
    x = np.pad(x, [(1, 1)] + [(0, 0)] * (x.ndim - 1))
    out.append(x.shape)
    x = np.zeros((n, 3))
    x = np.pad(x, ((1, 1), (0, 0)))
    out.append(x.shape)
    x = np.zeros((n, 3))
    x = np.tile(x, (2, 1))
    out.append(x.shape)
    x = np.zeros((n, 3))
    x = np.repeat(x, 2, axis=0)
    out.append(x.shape)
    x = np.zeros((n, 3))
    x = np.diff(x, axis=0)
    out.append(x.shape)
    x = np.zeros((n, 3))
    x = np.rot90(np.rot90(x))
    out.append(x.shape)
    x = np.zeros((n, 3))
    x = np.dot(x, P)
    out.append(x.shape)
    x = np.zeros((n, 3))
    x = x @ P
    out.append(x.shape)
    x = np.zeros((n, 3))
    x = np.einsum('ij,jk->ik', x, R)
    out.append(x.shape)
    x = np.zeros((n, 3))
    x = np.cross(x, y)
    out.append(x.shape)
    x = np.zeros((n, 3))
    x = np.moveaxis(np.moveaxis(x, 0, -1), -1, 0)
    out.append(x.shape)
    x = np.zeros((n, 3))
    x = np.array_split(x, 2)[0]
    out.append(x.shape)
    x = np.zeros((n, 3))
    x = np.resize(x, x.shape)
    out.append(x.shape)
    x = np.zeros((n, 3))
    x = np.broadcast_to(x, (n, 3))
    out.append(x.shape)
    x = np.zeros((n, 3))
    x = np.squeeze(x[:, None], 1)
    out.append(x.shape)
    x = np.zeros((n, 3))
    x = np.real(np.fft.ifft(np.fft.fft(x, axis=0), axis=0))
    out.append(x.shape)
    x = np.zeros((n, 3))
    x = np.take_along_axis(x, np.argsort(x, axis=0), axis=0)
    out.append(x.shape)
    x = np.zeros((n, 3))
    x = np.select([x > 0], [x], 0.0)
    out.append(x.shape)
    x = np.zeros((n, 3))
    x = np.linalg.solve(np.eye(n), x)
    out.append(x.shape)
    return out


